import{_ as a,c as e,o as s,ae as i}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse('{"title":"Product Management (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/product-management.md","filePath":"api/workflows/admin/product-management.md"}'),o={name:"api/workflows/admin/product-management.md"};function n(r,t,d,l,p,c){return s(),e("div",null,t[0]||(t[0]=[i(`<h1 id="product-management-admin" tabindex="-1">Product Management (Admin) <a class="header-anchor" href="#product-management-admin" aria-label="Permalink to &quot;Product Management (Admin)&quot;">​</a></h1><p>Creating and editing products is the most structured admin flow — seven product types, a two-step create, a partial-update that can silently wipe fields if misused, and separate sub-panels for images, inventory, and prices. This page is the theory; open each linked endpoint page for the exact body.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; send as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. Product create/edit needs the product-create / product-edit permission (else <code>403</code>).</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="two-product-endpoints-—-don-t-confuse-them" tabindex="-1">Two product endpoints — don&#39;t confuse them <a class="header-anchor" href="#two-product-endpoints-—-don-t-confuse-them" aria-label="Permalink to &quot;Two product endpoints — don&#39;t confuse them&quot;">​</a></h2><ul><li><strong><code>GET /api/admin/catalog/products</code></strong> — the full <strong>datagrid listing</strong> (all columns, filters, sort, mass-actions). This is the Products management screen: <a href="/api/rest-api/admin/catalog/products/list.html">list</a>.</li><li><strong><code>GET /api/admin/products</code></strong> — a <strong>slim Add-Product search</strong> (sku/name/price/image/saleable only) used by <a href="/api/workflows/admin/create-order-flow.html">Create-Order</a>. Not the product listing.</li></ul><h2 id="first-the-schema-attributes-→-families-→-products" tabindex="-1">First, the schema: attributes → families → products <a class="header-anchor" href="#first-the-schema-attributes-→-families-→-products" aria-label="Permalink to &quot;First, the schema: attributes → families → products&quot;">​</a></h2><p>A product isn&#39;t created in a vacuum — it&#39;s built from an <strong>attribute family</strong>, and that family is a grouping of <strong>attributes</strong>. So the build order is schema first, data second:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  attr[&quot;Attributes&lt;br/&gt;the fields&quot;] --&gt; fam[&quot;Attribute Family&lt;br/&gt;groups attributes&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fam --&gt; prod[&quot;Product&lt;br/&gt;built from a family&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  attr -.-&gt;|select types| opt[&quot;Attribute Options&lt;br/&gt;choosable values&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  opt -.-&gt; prod</span></span></code></pre></div><p>Attributes are the fields; a family groups them into the product form; a product is created against a family and renders that family&#39;s fields. Select-type attributes carry options (the choosable values).</p><ul><li><strong>Attributes</strong> are the dynamic fields a product can carry. Create one with <a href="/api/rest-api/admin/catalog/attributes/attributes-create.html">Attributes → Create</a> (<code>POST /api/admin/catalog/attributes</code>) — validates code (unique), admin name, type. An attribute of type <strong>select / multiselect / checkbox</strong> owns a set of <strong>options</strong> (the choosable values), managed as a sub-resource: <a href="/api/rest-api/admin/catalog/attributes/attribute-options.html">Attribute Options</a>. List/detail: <a href="/api/rest-api/admin/catalog/attributes/attributes-listing.html">listing</a> · <a href="/api/rest-api/admin/catalog/attributes/attributes-detail.html">detail</a>.</li><li><strong>Attribute Families</strong> group attributes (into attribute groups) into the form layout a product edit screen renders. Create one with <a href="/api/rest-api/admin/catalog/families/families-create.html">Families → Create</a> (<code>POST /api/admin/catalog/families</code>); its detail returns <code>attributeGroups: [{ code, name, column, position, attributes: [...] }]</code> — the column layout of the product form. List/detail: <a href="/api/rest-api/admin/catalog/families/families-listing.html">listing</a> · <a href="/api/rest-api/admin/catalog/families/families-detail.html">detail</a>.</li><li><strong>Products</strong> are created <strong>against a family</strong> — <code>attribute_family_id</code> is required at step 1, and that family decides which attribute fields step 2 can fill. For a <strong>configurable</strong> product, the <code>super_attributes</code> you pass are the ids/codes of select-type attributes (e.g. color, size) whose <strong>options</strong> generate the variant matrix — so those attributes and their options must exist first.</li></ul><p>So: build (or reuse) the attributes and the family before creating the product. In a fresh store the default family already carries the common attributes, so most tools surface Products first and treat Attributes / Families as configuration screens.</p><h2 id="create-is-a-two-step-wizard" tabindex="-1">Create is a two-step wizard <a class="header-anchor" href="#create-is-a-two-step-wizard" aria-label="Permalink to &quot;Create is a two-step wizard&quot;">​</a></h2><p>Mirror the admin panel — <strong>don&#39;t send the whole product in one call.</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fam[&quot;Pick attribute family&quot;] --&gt; step1[&quot;Step 1: create&lt;br/&gt;sku + family + type&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step1 --&gt;|configurable| sa[&quot;super_attributes&lt;br/&gt;→ variant matrix&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step1 --&gt; row[&quot;Barebones row&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  sa --&gt; row</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  row --&gt; step2[&quot;Step 2: update&lt;br/&gt;attributes + structures&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  step2 --&gt; subs[&quot;Sub-panels:&lt;br/&gt;images / inventory / prices&quot;]</span></span></code></pre></div><ol><li><strong>Step 1 — <a href="/api/rest-api/admin/catalog/products/create.html">Create</a></strong> (<code>POST /api/admin/catalog/products</code>). Body <code>{ sku, attribute_family_id, type? }</code> (<code>type</code> defaults <code>simple</code>). Validates <code>sku</code> (required, unique, slug-safe) and <code>attribute_family_id</code> (required, exists). Creates a barebones row.</li><li><strong>Step 2 — <a href="/api/rest-api/admin/catalog/products/update.html">Update</a></strong> (<code>PUT /api/admin/catalog/products/{id}</code>) fills the family&#39;s attribute fields, type structures, categories, etc.</li></ol><p><strong>Seven types:</strong> simple / virtual / downloadable / grouped / bundle / configurable / booking.</p><ul><li><strong>Configurable</strong> needs <code>super_attributes</code> at step 1 — a map of attribute <strong>code or id → option ids</strong> (both shapes accepted). The backend generates the full variant matrix from it. Omit it and create returns 422.</li><li><strong>Booking</strong> sub-types (default / appointment / event / rental / table) and their slots/tickets are configured in step 2, not step 1.</li></ul><h3 id="step-1-body-—-by-type" tabindex="-1">Step 1 body — by type <a class="header-anchor" href="#step-1-body-—-by-type" aria-label="Permalink to &quot;Step 1 body — by type&quot;">​</a></h3><p>A simple product needs only three fields:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sku&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tshirt-basic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;attribute_family_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;simple&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A configurable product adds <code>super_attributes</code> (here color = options 1,2,3 and size = options 4,5) — the backend builds one variant per combination:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sku&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tshirt-config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;attribute_family_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;configurable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;super_attributes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>What each type needs at step 1, and what step 2 fills:</p><table tabindex="0"><thead><tr><th>Type</th><th>Step 1</th><th>Step 2 fills</th></tr></thead><tbody><tr><td>simple / virtual</td><td>sku + family (+ type)</td><td>attribute values, price, categories</td></tr><tr><td>downloadable</td><td>sku + family + <code>type</code></td><td>attribute values + <code>downloadable_links</code> / <code>downloadable_samples</code></td></tr><tr><td>grouped</td><td>sku + family + <code>type</code></td><td>attribute values + <code>links</code> (the grouped child products)</td></tr><tr><td>bundle</td><td>sku + family + <code>type</code></td><td>attribute values + <code>bundle_options</code></td></tr><tr><td>configurable</td><td>sku + family + <code>type</code> + <code>super_attributes</code></td><td>attribute values on the parent; variants already generated</td></tr><tr><td>booking</td><td>sku + family + <code>type</code></td><td>attribute values + <code>booking</code> (sub-type + slots/tickets)</td></tr></tbody></table><h3 id="step-2-body-—-partial-update" tabindex="-1">Step 2 body — partial update <a class="header-anchor" href="#step-2-body-—-partial-update" aria-label="Permalink to &quot;Step 2 body — partial update&quot;">​</a></h3><p>Send only what changed. This sets the English name + price and assigns two categories, leaving everything else intact:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Basic T-Shirt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;price&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">19.99</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;categories&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Pass <code>?locale=fr&amp;channel=default</code> to write translatable values (name, description, meta) into a specific locale — one locale per request.</p><h2 id="update-is-a-partial-patch-—-and-has-wipe-traps" tabindex="-1">Update is a partial PATCH — and has wipe traps <a class="header-anchor" href="#update-is-a-partial-patch-—-and-has-wipe-traps" aria-label="Permalink to &quot;Update is a partial PATCH — and has wipe traps&quot;">​</a></h2><p>Send only the fields you change; every family attribute is editable by its <strong>code</strong>. But some structures <strong>replace</strong> on send and others get <strong>wiped if the core full-form path runs</strong> — know which:</p><ul><li><strong>Attribute values</strong> — send any family attribute code (<code>name</code>, <code>price</code>, <code>color</code>, <code>meta_title</code>, …). Translatable values write to the requested locale — pass <code>?locale=fr&amp;channel=default</code> (one locale per request).</li><li><strong>Type structures</strong> (<code>variants</code>, <code>bundle_options</code>, <code>links</code>, <code>downloadable_links</code>, <code>downloadable_samples</code>, <code>booking</code>) — sending one <strong>replaces</strong> that whole structure.</li><li><strong>Relations</strong> (<code>categories</code>, <code>channels</code>, up/cross/related-sells) — sending replaces the set; <strong>omitting preserves</strong> it.</li><li><strong>Sub-panel data</strong> (<code>images</code>, <code>videos</code>, <code>inventories</code>, <code>customer_group_prices</code>) — <strong>ignored here</strong>; they have dedicated endpoints (below). The response lists them under a warnings hint.</li></ul><p>Gotcha: an attribute-only edit uses a surgical write that touches only the sent values; a structure-bearing edit runs the full-form path that reconstructs current state first. So a partial edit does not clobber booleans/variants/relations — as long as you don&#39;t send an empty structure key. <strong>Open the <a href="/api/rest-api/admin/catalog/products/update.html">Update page</a> before writing a partial update.</strong></p><h2 id="sub-panels-image-inventory-price-tabs" tabindex="-1">Sub-panels (image / inventory / price tabs) <a class="header-anchor" href="#sub-panels-image-inventory-price-tabs" aria-label="Permalink to &quot;Sub-panels (image / inventory / price tabs)&quot;">​</a></h2><p>Each is parent-scoped under <code>/catalog/products/{productId}/…</code> and mirrors a tab on the edit screen:</p><table tabindex="0"><thead><tr><th>Sub-panel</th><th>Operations</th></tr></thead><tbody><tr><td><strong>Images</strong></td><td><a href="/api/rest-api/admin/catalog/products/images-upload.html">upload</a> (REST multipart only — binary <code>image</code> part, ≤4 MB; GraphQL upload is rejected) · <a href="/api/rest-api/admin/catalog/products/images-reorder.html">reorder</a> · <a href="/api/rest-api/admin/catalog/products/images-delete.html">delete</a></td></tr><tr><td><strong>Videos</strong></td><td><a href="/api/rest-api/admin/catalog/products/videos-upload.html">upload</a> (REST multipart) · <a href="/api/rest-api/admin/catalog/products/videos-delete.html">delete</a></td></tr><tr><td><strong>Inventory</strong></td><td><a href="/api/rest-api/admin/catalog/products/inventories-list.html">list</a> (<code>meta.totalQty</code> sums sources) · <a href="/api/rest-api/admin/catalog/products/inventories-update.html">bulk update</a> (<code>{ inventories: { sourceId: qty } }</code>; omitted sources untouched, <code>qty=0</code> zeroes)</td></tr><tr><td><strong>Customer-group prices</strong></td><td><a href="/api/rest-api/admin/catalog/products/customer-group-prices-list.html">list</a> · <a href="/api/rest-api/admin/catalog/products/customer-group-prices-create.html">create</a> · <a href="/api/rest-api/admin/catalog/products/customer-group-prices-update.html">update</a> · <a href="/api/rest-api/admin/catalog/products/customer-group-prices-delete.html">delete</a> (<code>{ qty, value_type: fixed|discount, value, customer_group_id }</code>; null group = all groups; <code>(qty, group)</code> unique)</td></tr><tr><td><strong>Downloadable</strong></td><td><a href="/api/rest-api/admin/catalog/products/downloadable-upload.html">file upload</a> · <a href="/api/rest-api/admin/catalog/products/downloadable-download.html">download</a> (REST binary)</td></tr></tbody></table><h2 id="managing-images-videos-files-—-the-flow" tabindex="-1">Managing images, videos &amp; files — the flow <a class="header-anchor" href="#managing-images-videos-files-—-the-flow" aria-label="Permalink to &quot;Managing images, videos &amp; files — the flow&quot;">​</a></h2><p>Uploads follow <strong>two different patterns</strong>. Getting this right matters, because one saves immediately and the other needs a follow-up product update.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  edit[&quot;Editing a product&quot;] --&gt; imgvid[&quot;Images / Videos&lt;br/&gt;upload (multipart, REST)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  imgvid --&gt; saved[&quot;Saved immediately&lt;br/&gt;row inserted + file stored&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  edit --&gt; dl[&quot;Downloadable file&lt;br/&gt;upload (multipart, REST)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  dl --&gt; path[&quot;Returns a path&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  path --&gt; upd[&quot;Update product (PUT)&lt;br/&gt;set the path on the link/sample&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  edit --&gt; variant[&quot;Variant image&lt;br/&gt;upload to the variant&#39;s product id&quot;]</span></span></code></pre></div><ul><li><strong>Images &amp; videos are one-step.</strong> The upload endpoint <strong>inserts the row and stores the file immediately</strong> and returns the created record. There is no &quot;save it in the product update&quot; step — the upload <em>is</em> the save. To change one: delete + re-upload (or reorder images).</li><li><strong>Downloadable files are two-step.</strong> The upload endpoint only <strong>stores the file and returns a <code>path</code></strong>. You then set that <code>path</code> on the link/sample in the <strong>product update</strong> (<code>PUT</code>). This is the only media flow that rides along with the product update.</li><li><strong>Variant images</strong> attach to the variant, and a configurable variant is its <strong>own product</strong> — upload to <code>POST /catalog/products/{variantId}/images</code> using the variant&#39;s id.</li><li><strong>A GraphQL admin client uses REST only for the binary.</strong> All uploads are REST multipart (a file cannot travel in GraphQL); reading, reordering, and deleting work over GraphQL. The GraphQL upload mutation is a placeholder that rejects with a pointer to REST.</li></ul><h2 id="copy-mass-actions" tabindex="-1">Copy &amp; mass-actions <a class="header-anchor" href="#copy-mass-actions" aria-label="Permalink to &quot;Copy &amp; mass-actions&quot;">​</a></h2><ul><li><strong><a href="/api/rest-api/admin/catalog/products/copy.html">Copy</a></strong> — <code>POST /api/admin/catalog/products/{sourceId}/copy</code>. Refuses a variant (can&#39;t copy standalone) → 422. Returns the new product&#39;s id + auto-suffixed sku.</li><li><strong><a href="/api/rest-api/admin/catalog/products/mass-delete.html">Mass-delete</a></strong> · <strong><a href="/api/rest-api/admin/catalog/products/mass-update-status.html">Mass-update-status</a></strong> — <code>{ indices: int[] }</code> (+ <code>value: 0|1</code> for status). Best-effort: missing ids silently skipped.</li><li><strong><a href="/api/rest-api/admin/catalog/products/export.html">Export</a></strong> — CSV of the datagrid honouring the listing filters; send <code>Accept: text/csv</code>, <code>?format=csv</code> only. REST-only.</li></ul><h2 id="graphql-notes" tabindex="-1">GraphQL notes <a class="header-anchor" href="#graphql-notes" aria-label="Permalink to &quot;GraphQL notes&quot;">​</a></h2><p>Query fields: <code>adminCatalogProducts</code> (list), <code>adminCatalogProduct</code> (detail). Mutations: <code>createAdminCatalogProduct</code>, <code>updateAdminCatalogProduct</code>, <code>deleteAdminCatalogProduct</code>, <code>createAdminCatalogProductCopy</code>, <code>createAdminCatalogProductMassDelete</code>, <code>createAdminCatalogProductMassUpdateStatus</code>. On create/update mutations the nested connections (images, variants, …) come back empty — re-query <code>adminCatalogProduct</code> for them. On <strong>mass-actions</strong> select the result fields, not a generic <code>id</code> (see the <a href="/api/workflows/admin/#graphql-the-must-know-rules">result-field rule</a>).</p><h2 id="status-codes-to-handle" tabindex="-1">Status codes to handle <a class="header-anchor" href="#status-codes-to-handle" aria-label="Permalink to &quot;Status codes to handle&quot;">​</a></h2><p><code>200/201</code> success · <code>401</code> unauthenticated · <code>403</code> permission · <code>400</code> bad input · <code>404</code> not found · <code>422</code> validation (missing <code>super_attributes</code>, copying a variant, bad option ids).</p>`,46)]))}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
